const body = $json.body ?? $json;
if (!body.patient_id || !body.thread_id || typeof body.question !== 'string' || body.question.trim().length === 0) throw new Error('INVALID_QUESTION_CONTRACT');
return [{ json: { answer: 'The uploaded record does not contain enough verified evidence to answer this question.', answer_status: 'insufficient', risk_level: 'informational', confidence: 0, citations: [], safety_message: 'This application does not provide a diagnosis. Do not start, stop, or change medication based on this result. Please verify high-risk or uncertain findings with a doctor or pharmacist.', patient_id: body.patient_id, thread_id: body.thread_id, prompt_version: 'qa-agent/v1' } }];
